import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    k = int(input_data[1])
    s = input_data[2]

    def max_beauty_for_char(target_char):
        left = 0
        changes_needed = 0
        max_len = 0

        for right in range(n):
            if s[right] != target_char:
                changes_needed += 1

            while changes_needed > k:
                if s[left] != target_char:
                    changes_needed -= 1
                left += 1

            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len

        return max_len

    result_a = max_beauty_for_char('a')
    result_b = max_beauty_for_char('b')

    print(max(result_a, result_b))

if __name__ == "__main__":
    solve()
